
window.PAINT_SHOPS_V20=Object.freeze([
  Object.freeze({id:'paint-downtown-east',name:'DOWNTOWN PAINT & SPRAY',x:-260,z:610,heading:Math.PI,style:{accent:0x20e3ff}}),
  Object.freeze({id:'paint-downtown-west',name:'MIDTOWN PAINT & SPRAY',x:-1280,z:80,heading:Math.PI/2,style:{accent:0xff2d9b}}),
  Object.freeze({id:'paint-docks',name:'DOCKS PAINT & SPRAY',x:-1040,z:2250,heading:Math.PI/2,style:{accent:0xffd23f}}),
  Object.freeze({id:'paint-airport',name:'AIRPORT PAINT & SPRAY',x:690,z:2820,heading:0,style:{accent:0x20e3ff}}),
  Object.freeze({id:'paint-retail',name:'RETAIL PAINT & SPRAY',x:1980,z:920,heading:Math.PI,style:{accent:0xff7abf}}),
  Object.freeze({id:'paint-hills',name:'HILLS PAINT & SPRAY',x:-2310,z:-1210,heading:Math.PI/2,style:{accent:0x3bff8b}}),
  Object.freeze({id:'paint-crown',name:'HILLS CITY PAINT & SPRAY',x:-4480,z:-860,heading:Math.PI/2,style:{accent:0x67e7ff}}),
  Object.freeze({id:'paint-island',name:'ISLAND PAINT & SPRAY',x:690,z:5200,heading:Math.PI/2,style:{accent:0x20e3ff}}),
  Object.freeze({id:'paint-links',name:'LINKS PAINT & SPRAY',x:2440,z:-760,heading:0,style:{accent:0xff2d9b}})
]);
/* Automatic Paint & Spray sequence at dedicated standalone shops. */
(function(){
'use strict';if(!window.GameSystems)return;
let ctx=null,active=null,doors=[],puffs=[];const hex=n=>'#'+(n>>>0).toString(16).padStart(6,'0'),COLORS=[0xff2d9b,0x20e3ff,0xffd23f,0x3bff8b,0xff4d3a,0xa66bff,0xf2f5ff,0x161c28,0x2f6bff];
function local(def,x,z){const dx=x-def.x,dz=z-def.z,c=Math.cos(def.heading),si=Math.sin(def.heading);return{x:dx*c-dz*si,z:dx*si+dz*c};}
function buildDoor(source){const def=Object.assign({},source,{style:source.style}),T=ctx.THREE,rg=GameSystems.api('roadgraph'),r=rg&&rg.nearest?rg.nearest(def.x,def.z,0):null;if(r){const side=(def.id.length&1)?1:-1,nx=Math.cos(r.heading),nz=-Math.sin(r.heading),off=r.width*.5+12;def.x=r.x+nx*off*side;def.z=r.z+nz*off*side;def.heading=r.heading+(side<0?Math.PI:0);}const g=new T.Group(),accent=def.style.accent,wall=new T.MeshStandardMaterial({color:0x1d2530,roughness:.72}),roof=new T.MeshStandardMaterial({color:0x0d1118,roughness:.8}),doorMat=new T.MeshStandardMaterial({color:0x344150,emissive:accent,emissiveIntensity:.18,roughness:.45,metalness:.65}),mk=(w,h,d,mat,x,y,z)=>{const m=new T.Mesh(new T.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m;};mk(30,9,20,wall,0,4.5,0);mk(32,.8,22,roof,0,9.2,0);mk(22,.25,18,new T.MeshStandardMaterial({color:0x343a43}),0,.12,11);const door=mk(15.4,6,.38,doorMat,0,8.4,10.1),sign=mk(20,1.3,.55,new T.MeshStandardMaterial({color:accent,emissive:accent,emissiveIntensity:1.2}),0,7.6,10.2);g.position.set(def.x,ctx.world.groundHeightAt(def.x,def.z,0),def.z);g.rotation.y=def.heading;ctx.scene.add(g);doors.push({def,g,door});}
function sync(){for(const d of doors)d.g.visible=(d.def.worldId||'neon')===ctx.world.id;}
function spraySound(){if(document.hidden||ctx.audio.muted)return;if(!ctx.audio.ctx){try{ctx.audio.ensure();}catch(_){}}const ac=ctx.audio.ctx;if(!ac)return;const len=Math.floor(ac.sampleRate*.22),b=ac.createBuffer(1,len,ac.sampleRate),data=b.getChannelData(0);for(let i=0;i<len;i++)data[i]=(Math.random()*2-1)*(1-i/len);const src=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();src.buffer=b;f.type='highpass';f.frequency.value=2300;g.gain.setValueAtTime(.13,ac.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.22);src.connect(f);f.connect(g);g.connect(ac.destination);src.start();}
function puff(color){const T=ctx.THREE,m=new T.Mesh(new T.SphereGeometry(.55,6,5),new T.MeshBasicMaterial({color,transparent:true,opacity:.32,depthWrite:false}));m.position.set(ctx.player.x+(Math.random()-.5)*5,ctx.carState.y+1+Math.random()*2.2,ctx.player.z+(Math.random()-.5)*5);ctx.scene.add(m);puffs.push({m,t:.7,vx:(Math.random()-.5)*2,vy:1+Math.random(),vz:(Math.random()-.5)*2});}
function start(def,door){const now=performance.now();if(door.cool&&now<door.cool)return;door.cool=now+7000;const old=ctx.vehicles.color;let col=old;for(let i=0;i<10&&col===old;i++)col=COLORS[(Math.random()*COLORS.length)|0];active={def,door,t:0,color:col,wanted:ctx.stats.wanted,painted:false,repaired:false,lastSpray:0};document.body.classList.add('paint-spray-active');if(ctx.input.clearAll)ctx.input.clearAll('paint-spray-open');ctx.carState.speed=0;ctx.carState.vx=0;ctx.carState.vz=0;ctx.engine.setWanted(0);ctx.actors.cops.forEach((cop,i)=>{const away=Math.atan2(cop.x-ctx.player.x,cop.z-ctx.player.z)+(i-(ctx.actors.cops.length-1)*.5)*.12;cop.heading=away;cop.vx=Math.sin(away)*28;cop.vz=Math.cos(away)*28;cop.ramCd=Math.max(cop.ramCd||0,3.5);});const radio=GameSystems.api('radio');if(radio&&radio.duck)radio.duck(4);ctx.fx.banner('PAINT & SPRAY','DOORS CLOSING', '#'+def.style.accent.toString(16).padStart(6,'0'));}
function finish(){const a=active;if(!a)return;ctx.engine.setWanted(Math.max(0,a.wanted-2));ctx.fx.banner('FRESH PAINT','REPAIRED · WANTED REDUCED','#3bff8b');document.body.classList.remove('paint-spray-active');ctx.camera.fov=70;ctx.camera.updateProjectionMatrix();a.door.cool=performance.now()+5000;active=null;}
function updatePuffs(dt){for(let i=puffs.length-1;i>=0;i--){const p=puffs[i];p.t-=dt;p.m.position.x+=p.vx*dt;p.m.position.y+=p.vy*dt;p.m.position.z+=p.vz*dt;p.m.material.opacity=Math.max(0,p.t*.42);p.m.scale.multiplyScalar(1+dt*1.5);if(p.t<=0){p.m.geometry.dispose();p.m.material.dispose();if(p.m.parent)p.m.parent.remove(p.m);puffs.splice(i,1);}}}
function tick(dt){updatePuffs(dt);sync();if(!active){if(ctx.player.onFoot||ctx.player.dead||ctx.player.dying||ctx.engine.selectionOpen||document.body.classList.contains('game-paused'))return;for(const d of doors){if(!d.g.visible)continue;const q=local(d.def,ctx.player.x,ctx.player.z);if(Math.abs(q.x)<6.2&&q.z>-1.5&&q.z<6.6&&ctx.player.mph<42){start(d.def,d);break;}}return;}
 const a=active;a.t+=dt;ctx.carState.speed=0;ctx.carState.vx=0;ctx.carState.vz=0;ctx.carState.y=ctx.world.groundHeightAt(ctx.player.x,ctx.player.z,ctx.carState.y);if(ctx.player.carMesh){ctx.player.carMesh.position.set(ctx.player.x,ctx.carState.y,ctx.player.z);}
 const close=Math.min(1,a.t/.72),open=a.t>2.55?Math.min(1,(a.t-2.55)/.72):0,k=close*(1-open);a.door.door.position.y=8.4-5.35*k;
 if(a.t>.72&&a.t<2.45&&a.t-a.lastSpray>.16){a.lastSpray=a.t;spraySound();puff(a.color);}
 if(a.t>1.12&&!a.painted){a.painted=true;ctx.vehicles.setColor(a.color);const pg=GameSystems.api('progression');if(pg&&pg.setPaint)pg.setPaint(ctx.vehicles.currentKey,a.color);}
 if(a.t>1.55&&!a.repaired){a.repaired=true;if(ctx.engine.repairPowertrain)ctx.engine.repairPowertrain();ctx.events.emit('shop:repair',{source:'paintspray'});}
 const h=a.def.heading,fx=Math.sin(h),fz=Math.cos(h),rx=Math.cos(h),rz=-Math.sin(h);ctx.camera.position.set(ctx.player.x+rx*15-fx*10,ctx.carState.y+8.5,ctx.player.z+rz*15-fz*10);ctx.camera.lookAt(ctx.player.x,ctx.carState.y+1.5,ctx.player.z);ctx.camera.fov=58;ctx.camera.updateProjectionMatrix();
 if(a.t>3.42)finish();}
GameSystems.register({id:'paintspray',order:99,alwaysUpdate:true,init(c){ctx=c;(window.PAINT_SHOPS_V20||[]).forEach(buildDoor);const nav=GameSystems.api('nav');if(nav)for(const rec of doors){const d=rec.def;nav.addPOI({id:'paint-'+d.id,worldId:d.worldId||'neon',x:d.x,z:d.z,icon:'P',label:d.name,kind:'paint',color:hex(d.style.accent)});}sync();const help=GameSystems.api('help');if(help)help.addControls('PAINT & SPRAY',[['Drive in','Automatic repair, repaint and wanted reduction']]);},worldChanged(){sync();if(active)finish();},update(dt){tick(dt);},api:{get active(){return !!active;},trigger(id){const d=doors.find(x=>x.def.id===id);if(!d)return false;start(d.def,d);return true;},doors(){return doors.map(d=>({id:d.def.id,visible:d.g.visible}));}}});
})();
